INSERT INTO `dbxdb`.`emailtemplates` (`id`, `TemplateName`, `TemplateText`, `Subject`, `SenderName`, `SenderEmail`) VALUES ('213', 'BCT_ENROLLMENT_USERNAME_TEMPLATE', '<p>&nbsp;</p><center><img src=\"https://ib1.himalayanbank.com/images/brand-login.png\" alt=\"hbl_logo\"  style=\"width:550px; display: block; margin-left: auto; margin-right: auto;\"/><br /><br /> <br /><table align=\"center\" style=\"width: 600px;\" ><tr><td style=\"border-style: solid; border-width: 6px; border-color: black;\"><br /><p  style=\"margin-left: 10px;\"> USER ACTIVATION NOTIFICATION <br /><br />Dear %firstName% %lastName%,<br /><br />You are enrolled to Digital Banking Channel. Please activate your account now.<br /><br />%userName% is your username. Activation code is %otp% sent to your registered mobile number.<br /><br />You are required to input your username &amp; activation code in the link below.<br /><br /><center>To activate your account and set a password,<a style=\"color: #11abeb;\" href=\"%resetPasswordLink%\">click here</a> <br />or paste the following link on your browser: <br /><br /><a style=\"color: #11abeb;\">%resetPasswordLink%</a><br/><br/>The activation code will expire in %activationCodeExpiry% days , so activate it right away.</center></p><br /><br /><br /></td></tr><tr><td><br /><b>Auto-generated Email Notification. Please do not reply to this email address.</b> <br /><br />The information in this mail is confidential and is intended solely for the addressee. Access to this mail by anyone else is unauthorized. Copying or further distribution beyond the original recipient may be unlawful. <br /><br /></td></tr></table></center>', 'Account Activation', 'Infinity', 'dbx_cl@infinity.com');
INSERT INTO `dbxdb`.`emailtemplates` (`id`, `TemplateName`, `TemplateText`, `Subject`, `SenderName`, `SenderEmail`) VALUES ('214', 'HBL_ENROLLMENT_REJECTED_TEMPLATE', '<p>&nbsp;</p><center><img src=\"https://ib1.himalayanbank.com/images/brand-login.png\" alt=\"hbl_logo\"  style=\"width:550px; display: block; margin-left: auto; margin-right: auto;\"/><br /><br /> <br /><table align=\"center\" style=\"width: 600px;\" ><tr><td style=\"border-style: solid; border-width: 6px; border-color: black;\"><br /><p  style=\"margin-left: 10px;\"> USER ACTIVATION NOTIFICATION <br /><br />Dear %firstName% %lastName%,<br /><br />Please note that your registration request for HBL Digital Banking cannot be completed due to some limitations. For details, please contact your branch or call us @ 01-5971399 or contact us through viber / whatsapp on 9803560838.<br /><br />We apologize for any inconvenience caused to you.<br /><br/><br />Thank you.<br /><br />Himalayan Bank<br/>Card & Digital Channel Center.<br ></p><br /></td></tr><tr><td><br /><b>Auto-generated Email Notification. Please do not reply to this email address.</b> <br /><br />The information in this mail is confidential and is intended solely for the addressee. Access to this mail by anyone else is unauthorized. Copying or further distribution beyond the original recipient may be unlawful. <br /><br /></td></tr></table></center>', 'Enrollment Rejected', 'Infinity', 'dbx_cl@infinity.com');



---------------updated custome email templates with HBL Format --------------------

UPDATE `dbxdb`.`emailtemplates` SET `TemplateText` = '<table style=\"border-color:#e0e0e0;border-style:solid;margin:auto;max-width:600px;\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" bgcolor=\"#FFFFFF\"> <tbody> <tr> <td style=\"padding:20px 0;text-align:center;vertical-align:middle;\"> <figure class=\"image image_resized\" style=\"height:auto;margin:auto;width:270px;\"><img style=\"display:block;\" src=\"http://himalayanbank.com/int/notification/logo/HBL-Logo-280x56.png\" alt=\"Himalayan Bank\"></figure> </td> </tr> <tr> <td style=\"background-color:#a72c32;color:#ffffff;font-family:Verdana, Arial;font-size:13px;padding:15px 0;text-align:center;\"><strong>HBL I-BANKING THIRD PARTY AUTHENTICATION NOTIFICATION </strong> </td> <tr> <td style=\"padding:15pt 11.25pt;\"> <p>Dear %userName%, Your third party authentication has been reset.</p> <p>Go to the I-Banking login page &amp; click on&nbsp; <a href=\"https://infinityqa.himalayanbank.com/apps/OnlineBanking/#/OnlineBanking/frmActivateThirdParties?data=thirdpartyauth\" target=\"_blank\" rel=\"noopener noreferrer\" data-auth=\"NotApplicable\" data-linkindex=\"0\">Reset Third Party Auth?</a>. You will be redirected to a new page and&nbsp;you have to login with existing credentials to setup OTP. Please scan a QR code via Authenticator mobile app. </p> <p>Download the <strong> <span style=\"font-family:Aptos,sans-serif;\">Authenticator</span> </strong> app from Google PlayStore/AppleStore before starting the activation process. </p> <ul type=\"disc\" style=\"margin-bottom:0;\"> <li style=\"font-size:12pt;font-family:Aptos,sans-serif;margin:0;\">Google Playstore: <a href=\"https://play.google.com/store/apps/details?id=com.google.android.apps.authenticator2\" target=\"_blank\" rel=\"noopener noreferrer\" data-auth=\"NotApplicable\" data-linkindex=\"1\">https://play.google.com/store/apps/details?id=com.google.android.apps.authenticator2</a> </li> <li style=\"font-size:12pt;font-family:Aptos,sans-serif;margin:0;\">Apple Store: <a href=\"https://apps.apple.com/us/app/google-authenticator/id388497605\" target=\"_blank\" rel=\"noopener noreferrer\" data-auth=\"NotApplicable\" data-linkindex=\"2\">https://apps.apple.com/us/app/google-authenticator/id388497605</a> </li> </ul> </tr> <tr> <td style=\"font-family:Verdana, Arial;padding:20px 0;text-align:center;\"> <figure class=\"table\"> <table border=\"0\" width=\"100%\"> <tbody> <tr> <td style=\"color:#777;font-size:13px;text-align:center;\"><strong>Himalayan Bank Limited</strong></td> </tr> </tbody> </table> </figure> </td> </tbody> </table>' WHERE (`id` = '311');


UPDATE `dbxdb`.`emailtemplates` SET `TemplateText` = '<table style=\"border-color:#e0e0e0;border-style:solid;margin:auto;max-width:600px;\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" bgcolor=\"#FFFFFF\"> <tbody> <tr> <td style=\"padding:20px 0;text-align:center;vertical-align:middle;\"> <figure class=\"image image_resized\" style=\"height:auto;margin:auto;width:270px;\"><img style=\"display:block;\" src=\"http://himalayanbank.com/int/notification/logo/HBL-Logo-280x56.png\" alt=\"Himalayan Bank\"></figure> </td> </tr> <tr> <td style=\"background-color:#a72c32;color:#ffffff;font-family:Verdana, Arial;font-size:13px;padding:15px 0;text-align:center;\"><strong>Card Request Details</strong></td> </tr> <td style=\"padding:5px 15px;\"> <figure class=\"table\" style=\"width:85%;\"> <l>Dear Card Processing Team,</l> </br> </br> <l>This is to notify you of a new %cardType%  request for the following customer:</l> </br> </br> <table class=\"ck-table-resized\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\"> <tr> <td style=\"background-color:#f4f4f4;border-radius:5px;color:#12120d;font-family:Verdana, Arial;font-size:16px;padding:8px 20px;\"><strong>Customer Details</strong></td> </tr> <tbody> <tr> <td style=\"padding:8px 20px;\"> <figure class=\"table\"> <table style=\"font-family:Verdana, Arial;font-size:13px;\" border=\"0\" width=\"100%\"> <tbody> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Customer Name :</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%coreIdentifier%</td> </tr> </tbody> </table> </figure> </td> </tr> <tr> <td style=\"background-color:#f4f4f4;border-radius:5px;color:#12120d;font-family:Verdana, Arial;font-size:16px;padding:8px 20px;\"><strong>Requested Card Details</strong></td> </tr> <tr> <td style=\"padding:8px 20px;\"> <figure class=\"table\"> <table style=\"font-family:Verdana, Arial;font-size:13px;\" border=\"0\" width=\"100%\"> <tbody> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Application Reference No:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%referenceNumber%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Requested Card Type:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%cardType%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Requested Card Name:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%cardName%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Expected Name on the Card:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%nameOnTheCard%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Date of Request:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%requestdate%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Preferred branch for card collection:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%branchname%</td> </tr> </tbody> </table> </figure> </td> </tr> <tr> <td style=\"font-family:Verdana, Arial;font-size:13px;\">Please proceed with processing the %cardType% request and ensure that all necessary steps are followed.</td> </tr> <tr> </tr> </tbody> </table> </figure> </td> </tr> <tr> <td style=\"font-family:Verdana, Arial;padding:20px 0;text-align:center;\"> <figure class=\"table\"> <table border=\"0\" width=\"100%\"> <tbody> <tr> <td style=\"color:#777;font-size:13px;text-align:center;\"><strong>Himalayan Bank Limited</strong></td> </tr> </tbody> </table> </figure> </td> </tr> </tbody> </table>' WHERE (`id` = '232');


UPDATE `dbxdb`.`emailtemplates` SET `TemplateText` = '<table style=\"border-color:#e0e0e0;border-style:solid;margin:auto;max-width:600px;\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" bgcolor=\"#FFFFFF\"> <tbody> <tr> <td style=\"padding:20px 0;text-align:center;vertical-align:middle;\"> <figure class=\"image image_resized\" style=\"height:auto;margin:auto;width:270px;\"><img style=\"display:block;\" src=\"http://himalayanbank.com/int/notification/logo/HBL-Logo-280x56.png\" alt=\"Himalayan Bank\"></figure> </td> </tr> <tr> <td style=\"background-color:#a72c32;color:#ffffff;font-family:Verdana, Arial;font-size:13px;padding:15px 0;text-align:center;\"><strong>Card Request Details</strong></td> </tr> <td style=\"padding:5px 15px;\"> <figure class=\"table\" style=\"width:85%;\"> <l>Dear %customerName% ,</l> </br> </br> <l>Thank you for reaching out to HBL. We have received your request for a new %cardType%. Please find the details below:</l> </br> </br> <table class=\"ck-table-resized\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\"> <tbody> <tr> <td style=\"background-color:#f4f4f4;border-radius:5px;color:#12120d;font-family:Verdana, Arial;font-size:16px;padding:8px 20px;\"><strong>Requested Card Details</strong></td> </tr> <tr> <td style=\"padding:8px 20px;\"> <figure class=\"table\"> <table style=\"font-family:Verdana, Arial;font-size:13px;\" border=\"0\" width=\"100%\"> <tbody> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Application Reference No:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%referenceNumber%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Requested Card Type:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%cardType%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Requested Card Name:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%cardName%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Expected Name on the Card:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%nameOnTheCard%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Date of Request:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%requestdate%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Preferred branch for card collection:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%branchname%</td> </tr> </tbody> </table> </figure> </td> </tr> <tr> <td style=\"font-family:Verdana, Arial;font-size:13px;\">Our team is currently processing your request, and we will notify you once your card has been issued and shipped. Please allow %estimatedTime% for delivery. </br> </br>If you have any questions or need further assistance in the meantime, feel free to contact us at %customerCareNumber% </td> </tr> <tr> </tr> </tbody> </table> </figure> </td> </tr> <tr> <td style=\"font-family:Verdana, Arial;padding:20px 0;text-align:center;\"> <figure class=\"table\"> <table border=\"0\" width=\"100%\"> <tbody> <tr> <td style=\"color:#777;font-size:13px;text-align:center;\"><strong>Himalayan Bank Limited</strong></td> </tr> </tbody> </table> </figure> </td> </tr> </tbody> </table>' WHERE (`id` = '231');


