UPDATE `dbxdb`.`emailtemplates` SET `TemplateText` = '<table style=\"border-color:#e0e0e0;border-style:solid;margin:auto;max-width:600px;\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" bgcolor=\"#FFFFFF\"> <tbody> <tr> <td style=\"padding:20px 0;text-align:center;vertical-align:middle;\"> <figure class=\"image image_resized\" style=\"height:auto;margin:auto;width:270px;\"><img style=\"display:block;\" src=\"http://himalayanbank.com/int/notification/logo/HBL-Logo-280x56.png\" alt=\"Himalayan Bank\"></figure> </td> </tr> <tr> <td style=\"background-color:#a72c32;color:#ffffff;font-family:Verdana, Arial;font-size:13px;padding:15px 0;text-align:center;\"><strong>Transaction PIN Reset Request</strong></td> </tr> <td style=\"padding:5px 15px;\"> <figure class=\"table\" style=\"width:85%;\"> <l>Dear Admin,</l> </br></br> <l>A new Transaction PIN reset request has been raised for CIF %customerid% with the following details:</l> </br> <table class=\"ck-table-resized\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\"> <tbody> <tr> <td style=\"background-color:#f4f4f4;border-radius:5px;color:#12120d;font-family:Verdana, Arial;font-size:16px;padding:8px 20px;\"><strong>Request Details</strong></td> </tr> <tr> <td style=\"padding:8px 20px;\"> <figure class=\"table\"> <table style=\"font-family:Verdana, Arial;font-size:13px;\" border=\"0\" width=\"100%\"> <tbody> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Request ID:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%requestId%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Customer Name:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%customername%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Channel:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%channel%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:no