UPDATE `dbxdb`.`emailtemplates` SET `TemplateText` = '<table style=\"border-color:#e0e0e0;border-style:solid;margin:auto;max-width:600px;\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" bgcolor=\"#FFFFFF\"> <tbody> <tr> <td style=\"padding:20px 0;text-align:center;vertical-align:middle;\"> <figure class=\"image image_resized\" style=\"height:auto;margin:auto;width:270px;\"><img style=\"display:block;\" src=\"http://himalayanbank.com/int/notification/logo/HBL-Logo-280x56.png\" alt=\"Himalayan Bank\"></figure> </td> </tr> <tr> <td style=\"background-color:#a72c32;color:#ffffff;font-family:Verdana, Arial;font-size:13px;padding:15px 0;text-align:center;\"><strong>Transaction PIN Reset Request Approved</strong></td> </tr> <td style=\"padding:5px 15px;\"> <figure class=\"table\" style=\"width:85%;\"> <l>Dear %customername%,</l> </br></br> <l>We are pleased to inform you that your request to reset your Transaction PIN has been successfully approved.</l> </br> </br> <l>For your convenience, your temporary Transaction PIN is %temporaryPin%, and it will remain valid for %resetTemporaryValidity% hours.</l> </br> </br> <l>Please click <a href=\"https://infinityqa.himalayanbank.com/apps/OnlineBanking/#/OnlineBanking/?data=resetTransactionPin\" target=\"_blank\" rel=\"noopener noreferrer\" data-auth=\"NotApplicable\" data-linkindex=\"0\">here</a> to set up your new PIN.</l> </br> </br> <l>Kindly ensure that you reset your PIN at your earliest convenience to maintain the security of your account.</l> </br> </br> <l>If you have any questions or need further assistance, please feel free to contact our support team at %customecarenumber%.</l> </br> </br> <l>We are here to assist you!</l> </br> </figure> </td> </tr> <td style=\"font-family:Verdana, Arial;padding:20px 0;text-align:center;\"> <figure class=\"table\"> <table border=\"0\" width=\"100%\"> <tbody> <tr> <td style=\"color:#777;font-size:13px;text-align:center;\"><strong>Himalayan Bank Limited</strong></td> </tr> </tbody> </table> </figure> </td> </tbody> </table>' WHERE (`id` = '229');


UPDATE `dbxdb`.`emailtemplates` SET `TemplateText` = '<table style=\"border-color:#e0e0e0;border-style:solid;margin:auto;max-width:600px;\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" bgcolor=\"#FFFFFF\"> <tbody> <tr> <td style=\"padding:20px 0;text-align:center;vertical-align:middle;\"> <figure class=\"image image_resized\" style=\"height:auto;margin:auto;width:270px;\"><img style=\"display:block;\" src=\"http://himalayanbank.com/int/notification/logo/HBL-Logo-280x56.png\" alt=\"Himalayan Bank\"></figure> </td> </tr> <tr> <td style=\"background-color:#a72c32;color:#ffffff;font-family:Verdana, Arial;font-size:13px;padding:15px 0;text-align:center;\"><strong>Transaction PIN Reset Request Rejected</strong></td> </tr> <td style=\"padding:5px 15px;\"> <figure class=\"table\" style=\"width:85%;\"> <l>Dear %customername%,</l> </br></br> <l>We regret to inform you that your request to reset the Transaction PIN, with reference ID %referenceid%, has been rejected by our bank staff due to security concerns. If you have any questions or need further assistance, please feel free to contact our support team at %customecarenumber%. We are here to assist you!</l> </br> </br> <l>Thank you for your understanding.</l> </figure> </td> </tr> <td style=\"font-family:Verdana, Arial;padding:20px 0;text-align:center;\"> <figure class=\"table\"> <table border=\"0\" width=\"100%\"> <tbody> <tr> <td style=\"color:#777;font-size:13px;text-align:center;\"><strong>Himalayan Bank Limited</strong></td> </tr> </tbody> </table> </figure> </td> </tbody> </table>' WHERE (`id` = '228');


INSERT INTO `dbxdb`.`emailtemplates` (`id`, `TemplateName`, `TemplateText`, `Subject`, `SenderName`, `SenderEmail`) VALUES ('318', 'CARD_PAYMENT_EMAIL_TEMPLATE', '<table style=\"border-color:#e0e0e0;border-style:solid;margin:auto;max-width:600px;\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" bgcolor=\"#FFFFFF\"> <tbody> <tr> <td style=\"padding:20px 0;text-align:center;vertical-align:middle;\"> <figure class=\"image image_resized\" style=\"height:auto;margin:auto;width:270px;\"><img style=\"display:block;\" src=\"http://himalayanbank.com/int/notification/logo/HBL-Logo-280x56.png\" alt=\"Himalayan Bank\"></figure> </td> </tr> <tr> <td style=\"background-color:#a72c32;color:#ffffff;font-family:Verdana, Arial;font-size:13px;padding:15px 0;text-align:center;\"><strong>Credit Card Payment Transaction Details </strong></td> </tr> <td style=\"padding:5px 15px;\"> <figure class=\"table\" style=\"width:85%;\"> <table class=\"ck-table-resized\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\"> <tr> <td style=\"background-color:#f4f4f4;border-radius:5px;color:#12120d;font-family:Verdana, Arial;font-size:16px;padding:8px 20px;\"><strong>Transactions Details</strong></td> </tr> <tbody> <tr> <td style=\"padding:8px 20px;\"> <figure class=\"table\"> <table style=\"font-family:Verdana, Arial;font-size:13px;\" border=\"0\" width=\"100%\"> <tbody> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Transaction Id :</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%transactionId%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Transaction Amount :</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%transactionAmount%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Transaction Date :</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%transactionDate%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Remarks :</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%remarks%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Card Number :</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%cardNumber%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Card Account Number :</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%cardAccNumber%</td> </tr> </tbody> </table> </figure> </td> </tr> <tr> <td style=\"background-color:#f4f4f4;border-radius:5px;color:#12120d;font-family:Verdana, Arial;font-size:16px;padding:8px 20px;\"><strong>Customer Account Details</strong></td> </tr> <tr> <td style=\"padding:8px 20px;\"> <figure class=\"table\"> <table style=\"font-family:Verdana, Arial;font-size:13px;\" border=\"0\" width=\"100%\"> <tbody> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Debtor Name:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%debtorName%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Account Number:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%accountNumber%</td> </tr> </tbody> </table> </figure> </td> </tr> <tr> <td style=\"background-color:#f4f4f4;border-radius:5px;color:#12120d;font-family:Verdana, Arial;font-size:16px;padding:8px 20px;\"><strong>Beneficiary Details</strong></td> </tr> <tr> <td style=\"padding:8px 20px;\"> <figure class=\"table\"> <table style=\"font-family:Verdana, Arial;font-size:13px;\" border=\"0\" width=\"100%\"> <tbody> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Creditor Name:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%creditorname%</td> </tr> </tbody> </table> </figure> </td> </tr> </tbody> </table> </figure> </td> </tr> <tr> <td style=\"font-family:Verdana, Arial;padding:20px 0;text-align:center;\"> <figure class=\"table\"> <table border=\"0\" width=\"100%\"> <tbody> <tr> <td style=\"color:#777;font-size:13px;text-align:center;\"><strong>Himalayan Bank Limited</strong></td> </tr> </tbody> </table> </figure> </td> </tr> </tbody> </table>', 'Credit Card Payment Transaction Details', 'Infinity', 'dbx_cl@infinity.com');

INSERT INTO `dbxdb`.`emailtemplates` (`id`, `TemplateName`, `TemplateText`, `Subject`, `SenderName`, `SenderEmail`) VALUES ('319', 'CARD_TOPUP_TEMPLATE', '<table style=\"border-color:#e0e0e0;border-style:solid;margin:auto;max-width:600px;\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" bgcolor=\"#FFFFFF\"> <tbody> <tr> <td style=\"padding:20px 0;text-align:center;vertical-align:middle;\"> <figure class=\"image image_resized\" style=\"height:auto;margin:auto;width:270px;\"><img style=\"display:block;\" src=\"http://himalayanbank.com/int/notification/logo/HBL-Logo-280x56.png\" alt=\"Himalayan Bank\"></figure> </td> </tr> <tr> <td style=\"background-color:#a72c32;color:#ffffff;font-family:Verdana, Arial;font-size:13px;padding:15px 0;text-align:center;\"><strong>Credit Card Top-Up Details </strong></td> </tr> <td style=\"padding:5px 15px;\"> <figure class=\"table\" style=\"width:85%;\"> <table class=\"ck-table-resized\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\"> <tr> <td style=\"background-color:#f4f4f4;border-radius:5px;color:#12120d;font-family:Verdana, Arial;font-size:16px;padding:8px 20px;\"><strong>Transactions Details</strong></td> </tr> <tbody> <tr> <td style=\"padding:8px 20px;\"> <figure class=\"table\"> <table style=\"font-family:Verdana, Arial;font-size:13px;\" border=\"0\" width=\"100%\"> <tbody> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Transaction Type :</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">Card Top-Up</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Transaction Id :</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%transactionId%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Transaction Date :</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%transactionDate%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Transaction Status :</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%status%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Transaction Currency :</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%transCurrency%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Transaction Amount :</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%transactionAmount%</td> </tr> </tbody> </table> </figure> </td> </tr> <tr> <td style=\"background-color:#f4f4f4;border-radius:5px;color:#12120d;font-family:Verdana, Arial;font-size:16px;padding:8px 20px;\"><strong>Card Details</strong></td> </tr> <tr> <td style=\"padding:8px 20px;\"> <figure class=\"table\"> <table style=\"font-family:Verdana, Arial;font-size:13px;\" border=\"0\" width=\"100%\"> <tbody> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Card Product:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%cardProduct%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Card Type:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%cardType%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Card Number:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%cardNumber%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Name on Card:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%cardHolderName%</td> </tr> </tbody> </table> </figure> </td> </tr> <tr> <td style=\"background-color:#f4f4f4;border-radius:5px;color:#12120d;font-family:Verdana, Arial;font-size:16px;padding:8px 20px;\"><strong>Debit Account</strong></td> </tr> <tr> <td style=\"padding:8px 20px;\"> <figure class=\"table\"> <table style=\"font-family:Verdana, Arial;font-size:13px;\" border=\"0\" width=\"100%\"> <tbody> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Account Number:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%accountNumber%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Account Name:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%debtorName%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Currency:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%currency%</td> </tr> <tr> <td style=\"padding:4px 0px;white-space:nowrap;width:35%;\"><strong>Amount Debited:</strong></td> <td style=\"padding:4px 0px;white-space:nowrap;width:65%;\">%debitedAmount%</td> </tr> </tbody> </table> </figure> </td> </tr> </tbody> </table> </figure> </td> </tr> <tr> <td style=\"font-family:Verdana, Arial;padding:20px 0;text-align:center;\"> <figure class=\"table\"> <table border=\"0\" width=\"100%\"> <tbody> <tr> <td style=\"color:#777;font-size:13px;text-align:center;\"><strong>Himalayan Bank Limited</strong></td> </tr> </tbody> </table> </figure> </td> </tr> </tbody> </table>', 'Credit Card Top-Up Details', 'Infinity', 'dbx_cl@infinity.com');

